-- Product Learning Sync checked: brand-owned destination, verified source, test/live separation and immutable attempt receipts.
create table public.sv_measurement_consent(company_id uuid not null,customer_id text not null,brand_id text not null,allowed boolean not null,consented_at timestamptz not null,source text not null check(length(btrim(source))between 1 and 500),revision bigint not null default 0,primary key(company_id,customer_id,brand_id),foreign key(company_id,customer_id,brand_id)references public.sv_customer_brands(company_id,customer_id,brand_id));
create table public.sv_feedback_settings(company_id uuid not null references public.sv_companies(id),brand_id text not null,dataset_id text not null check(dataset_id~'^[1-9][0-9]{1,39}$'),business_id text not null,ad_account_id text not null,label text not null,encrypted_credentials jsonb not null,enabled boolean not null default false,mode text not null check(mode in('test','live')),test_code text,verified_at timestamptz not null,enabled_from timestamptz not null default statement_timestamp(),configured_by uuid not null,revision bigint not null default 0,primary key(company_id,brand_id),check(mode<>'test'or length(test_code)between 1 and 100));
create table public.sv_feedback_jobs(company_id uuid not null,brand_id text not null,id uuid not null default gen_random_uuid(),outcome_id uuid not null,dataset_id text not null,mode text not null,event_id text not null,event_name text not null check(event_name in('Schedule','Purchase')),state text not null default 'scheduled'check(state in('scheduled','dispatching','accepted','failed','unknown','skipped')),reason text,attempted_at timestamptz,finished_at timestamptz,receipt jsonb,created_at timestamptz not null default now(),primary key(company_id,id),unique(company_id,dataset_id,mode,event_id),foreign key(company_id,outcome_id)references public.sv_business_outcomes(company_id,id));
create index sv_feedback_due on public.sv_feedback_jobs(company_id,created_at,id)where state='scheduled';
create table public.sv_feedback_events(company_id uuid not null,id uuid not null default gen_random_uuid(),job_id uuid not null,kind text not null,detail jsonb not null,created_at timestamptz not null default statement_timestamp(),primary key(company_id,id),foreign key(company_id,job_id)references public.sv_feedback_jobs(company_id,id));
create function smartvolt_private.feedback_event()returns trigger language plpgsql security invoker set search_path=''as $$begin
 if tg_op='INSERT'or new.state is distinct from old.state then insert into public.sv_feedback_events(company_id,job_id,kind,detail)values(new.company_id,new.id,new.state,jsonb_build_object('reason',new.reason,'mode',new.mode,'eventId',new.event_id));end if;return new;end;$$;
create trigger sv_feedback_event after insert or update on public.sv_feedback_jobs for each row execute function smartvolt_private.feedback_event();
create function public.sv_feedback_receipt(p_company uuid,p_actor uuid,p_command uuid,p_request jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$begin
 perform public.sv_authorize(p_company,p_actor,'crm',true,true,p_request->>'brandId');return smartvolt_private.action_replay(p_company,p_actor,p_command,'feedback:setting',p_request);end;$$;
create function public.sv_feedback_action(p_company uuid,p_actor uuid,p_command uuid,p_kind text,p_data jsonb,p_request jsonb default null)returns jsonb language plpgsql security invoker set search_path=''as $$declare r jsonb;brand text:=p_data->>'brandId';rev bigint;begin
 perform public.sv_authorize(p_company,p_actor,'crm',true,p_kind<>'consent',brand);
 if p_kind='setting'and not exists(select 1 from public.sv_memberships where company_id=p_company and user_id=p_actor and role='owner')then raise exception 'access_denied';end if;
 if p_kind='consent'then perform public.sv_customer_scope(p_company,p_actor,p_data->>'customerId');end if;
 r=smartvolt_private.action_replay(p_company,p_actor,p_command,'feedback:'||p_kind,coalesce(p_request,p_data));if r is not null then return r;end if;
 if p_kind='setting'then
  select revision into rev from public.sv_feedback_settings where company_id=p_company and brand_id=brand for update;if coalesce(rev,0)<>(p_data->>'revision')::bigint then raise exception 'revision_conflict';end if;
  insert into public.sv_feedback_settings(company_id,brand_id,dataset_id,business_id,ad_account_id,label,encrypted_credentials,enabled,mode,test_code,verified_at,configured_by)
  values(p_company,brand,p_data->>'datasetId',p_data->>'businessId',p_data->>'adAccountId',p_data->>'label',p_data->'credentials',(p_data->>'enabled')::boolean,p_data->>'mode',p_data->>'testCode',statement_timestamp(),p_actor)
  on conflict(company_id,brand_id)do update set dataset_id=excluded.dataset_id,business_id=excluded.business_id,ad_account_id=excluded.ad_account_id,label=excluded.label,encrypted_credentials=excluded.encrypted_credentials,enabled=excluded.enabled,mode=excluded.mode,test_code=excluded.test_code,verified_at=excluded.verified_at,enabled_from=case when not sv_feedback_settings.enabled and excluded.enabled or sv_feedback_settings.dataset_id<>excluded.dataset_id or sv_feedback_settings.mode<>excluded.mode then statement_timestamp()else sv_feedback_settings.enabled_from end,configured_by=excluded.configured_by,revision=sv_feedback_settings.revision+1;
 elsif p_kind='consent'then
  select revision into rev from public.sv_measurement_consent where company_id=p_company and customer_id=p_data->>'customerId'and brand_id=brand for update;if coalesce(rev,0)<>(p_data->>'revision')::bigint then raise exception 'revision_conflict';end if;
  if(p_data->>'consentedAt')::timestamptz>statement_timestamp()or not isfinite((p_data->>'consentedAt')::timestamptz)then raise exception 'invalid_consent_time';end if;
  insert into public.sv_measurement_consent(company_id,customer_id,brand_id,allowed,consented_at,source)values(p_company,p_data->>'customerId',brand,(p_data->>'allowed')::boolean,(p_data->>'consentedAt')::timestamptz,p_data->>'source')on conflict(company_id,customer_id,brand_id)do update set allowed=excluded.allowed,consented_at=excluded.consented_at,source=excluded.source,revision=sv_measurement_consent.revision+1;
  insert into public.sv_customer_events(company_id,customer_id,brand_id,event_key,kind,actor_id,detail)values(p_company,p_data->>'customerId',brand,'measurement:'||p_command,'measurement-preference',p_actor,p_data);
 else raise exception 'invalid_action';end if;
 r='{"saved":true}';insert into public.sv_action_receipts(company_id,command_id,actor_id,kind,data,result)values(p_company,p_command,p_actor,'feedback:'||p_kind,coalesce(p_request,p_data),r);return r;
end;$$;
create function public.sv_feedback_prepare(p_company uuid)returns integer language plpgsql security invoker set search_path=''as $$declare n integer;begin
 update public.sv_feedback_jobs set state='unknown',reason='worker_interrupted'where company_id=p_company and state='dispatching'and attempted_at<statement_timestamp()-interval '2 minutes';
 insert into public.sv_feedback_jobs(company_id,brand_id,outcome_id,dataset_id,mode,event_id,event_name)
 select o.company_id,o.brand_id,o.id,s.dataset_id,s.mode,encode(sha256(convert_to(jsonb_build_array(o.company_id,o.brand_id,s.dataset_id,case when o.kind='confirmed'then 'Schedule'else 'Purchase'end,o.booking_key)::text,'UTF8')),'hex'),case when o.kind='confirmed'then 'Schedule'else 'Purchase'end
 from smartvolt_private.report_outcomes o join public.sv_feedback_settings s on s.company_id=o.company_id and s.brand_id=o.brand_id and s.enabled
 join public.sv_measurement_consent c on c.company_id=o.company_id and c.customer_id=o.customer_id and c.brand_id=o.brand_id and c.allowed and c.consented_at<=o.occurred_at
 where o.company_id=p_company and not o.baseline and o.kind in('confirmed','purchase')and o.occurred_at>=s.enabled_from and o.occurred_at>statement_timestamp()-interval '7 days'and o.occurred_at<=statement_timestamp()
 and not exists(select 1 from public.sv_feedback_jobs prior join smartvolt_private.report_outcomes previous on previous.company_id=prior.company_id and previous.id=prior.outcome_id where prior.company_id=o.company_id and prior.dataset_id=s.dataset_id and prior.mode=s.mode and previous.booking_key=o.booking_key and prior.event_name=case when o.kind='confirmed'then 'Schedule'else 'Purchase'end)
 and not exists(select 1 from public.sv_feedback_jobs j where j.company_id=o.company_id and j.dataset_id=s.dataset_id and j.mode=s.mode and j.event_id=encode(sha256(convert_to(jsonb_build_array(o.company_id,o.brand_id,s.dataset_id,case when o.kind='confirmed'then 'Schedule'else 'Purchase'end,o.booking_key)::text,'UTF8')),'hex'))order by o.observed_at,o.id limit 100 on conflict do nothing;
 get diagnostics n=row_count;return n;end;$$;
create function public.sv_feedback_claim(p_company uuid,p_job uuid,p_revision bigint)returns jsonb language plpgsql security invoker set search_path=''as $$declare j public.sv_feedback_jobs;s public.sv_feedback_settings;o public.sv_business_outcomes;why text;c public.sv_customers;begin
 select *into strict j from public.sv_feedback_jobs where company_id=p_company and id=p_job;
 select *into strict s from public.sv_feedback_settings where company_id=p_company and brand_id=j.brand_id for share;
 if s.revision<>p_revision then return jsonb_build_object('dispatch',false,'changed',true);end if;
 begin perform public.sv_authorize(p_company,s.configured_by,'crm',true,true,s.brand_id);select *into strict o from public.sv_business_outcomes where company_id=p_company and id=j.outcome_id;if o.product='pos'then perform public.sv_authorize(p_company,s.configured_by,'pos',false,true,s.brand_id);end if;exception when others then why='authority_changed';end;
 select *into strict j from public.sv_feedback_jobs where company_id=p_company and id=p_job for update;if j.state<>'scheduled'then return jsonb_build_object('dispatch',false);end if;
 if not exists(select 1 from public.sv_memberships where company_id=p_company and user_id=s.configured_by and status='active'and role='owner')then why='authority_changed';end if;
 if not s.enabled or(s.dataset_id,s.mode)<>(j.dataset_id,j.mode)then why='destination_changed';end if;
 if o.baseline or o.occurred_at<=statement_timestamp()-interval '7 days'or o.occurred_at<s.enabled_from then why='source_expired';end if;
 if not exists(select 1 from public.sv_measurement_consent where company_id=p_company and customer_id=o.customer_id and brand_id=o.brand_id and allowed and consented_at<=o.occurred_at for share)then why='measurement_consent_missing';end if;
 if o.kind='confirmed'and exists(select 1 from public.sv_business_outcomes x where x.company_id=p_company and x.source_key=o.source_key and x.kind='cancelled'and x.observed_at>o.observed_at)then why='source_cancelled';end if;
 if o.kind='purchase'and not exists(select 1 from public.sv_pos_orders ord where ord.company_id=p_company and ord.id=o.detail->>'orderId'and not ord.voided and ord.total_cents>0 and coalesce((select sum(amount_cents)from public.sv_pos_payments p where p.company_id=p_company and p.order_id=ord.id),0)-coalesce((select sum(amount_cents)from public.sv_pos_refunds p where p.company_id=p_company and p.order_id=ord.id),0)>=ord.total_cents)then why='payment_changed';end if;
 select *into c from public.sv_customers where company_id=p_company and id=o.customer_id;
 if c.id is null or not(c.phone~'^\+[1-9][0-9]{6,14}$'or c.email~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')then why='matching_data_missing';end if;
 if why is not null then update public.sv_feedback_jobs set state='skipped',reason=why,finished_at=statement_timestamp()where company_id=p_company and id=p_job;return jsonb_build_object('dispatch',false,'reason',why);end if;
 update public.sv_feedback_jobs set state='dispatching',attempted_at=statement_timestamp()where company_id=p_company and id=p_job;
 return jsonb_build_object('dispatch',true,'eventId',j.event_id,'eventName',j.event_name,'eventTime',floor(extract(epoch from o.occurred_at)),'amountCents',o.amount_cents,'currency',o.currency,'phone',c.phone,'email',c.email,'customerId',c.id,'brandId',o.brand_id,'source',o.source_key);
end;$$;
create function public.sv_feedback_finish(p_company uuid,p_job uuid,p_state text,p_reason text,p_receipt jsonb)returns void language plpgsql security invoker set search_path=''as $$begin
 if p_state not in('accepted','failed','unknown')or octet_length(coalesce(p_receipt,'{}')::text)>4096 then raise exception 'invalid_result';end if;
 update public.sv_feedback_jobs set state=p_state,reason=p_reason,receipt=p_receipt,finished_at=statement_timestamp()where company_id=p_company and id=p_job and state='dispatching';end;$$;
create function public.sv_feedback_read(p_company uuid,p_actor uuid,p_brand text default null,p_customer text default null,p_before timestamptz default null,p_id uuid default null)returns jsonb language plpgsql security invoker set search_path=''as $$begin
 perform public.sv_authorize(p_company,p_actor,'crm',false,p_customer is null,p_brand);if p_customer is not null then perform public.sv_customer_scope(p_company,p_actor,p_customer);end if;
 if p_customer is null and p_brand is null then select b->>'id'into p_brand from public.sv_workspaces w,jsonb_array_elements(w.payload#>'{scope,brands}')b where w.company_id=p_company and smartvolt_private.member_brand_allowed(p_company,p_actor,b->>'id')order by b->>'id'limit 1;end if;
 return jsonb_build_object('selectedBrand',p_brand,'brands',coalesce((select jsonb_agg(jsonb_build_object('id',b->>'id','name',b->>'name'))from public.sv_workspaces w,jsonb_array_elements(w.payload#>'{scope,brands}')b where w.company_id=p_company and smartvolt_private.member_brand_allowed(p_company,p_actor,b->>'id')),'[]'),'consents',coalesce((select jsonb_agg(jsonb_build_object('brandId',brand_id,'allowed',allowed,'consentedAt',consented_at,'source',source,'revision',revision))from public.sv_measurement_consent where company_id=p_company and customer_id=p_customer and smartvolt_private.member_brand_allowed(p_company,p_actor,brand_id)),'[]'),
 'settings',case when p_customer is not null then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('brandId',s.brand_id,'datasetId',s.dataset_id,'businessId',s.business_id,'adAccountId',s.ad_account_id,'label',s.label,'enabled',s.enabled,'mode',s.mode,'testCode',s.test_code,'verifiedAt',s.verified_at,'revision',s.revision))from public.sv_feedback_settings s where company_id=p_company and(p_brand is null or brand_id=p_brand)and smartvolt_private.member_brand_allowed(p_company,p_actor,brand_id)),'[]')end,
 'jobs',case when p_customer is not null then '[]'::jsonb else coalesce((select jsonb_agg(q order by q.created_at desc,q.id desc)from(select j.id,j.brand_id,j.event_name,j.mode,j.event_id,j.state,j.reason,j.receipt,j.created_at,o.source_key,o.product from public.sv_feedback_jobs j join public.sv_business_outcomes o on o.company_id=j.company_id and o.id=j.outcome_id where j.company_id=p_company and(p_brand is null or j.brand_id=p_brand)and smartvolt_private.member_brand_allowed(p_company,p_actor,j.brand_id)and(o.product='crm'or smartvolt_private.member_has_product(p_company,p_actor,'pos'))and(p_before is null or(j.created_at,j.id)<(p_before,p_id))order by j.created_at desc,j.id desc limit 31)q),'[]')end);
end;$$;
do $$declare t text;f record;begin
 foreach t in array array['sv_measurement_consent','sv_feedback_settings','sv_feedback_jobs','sv_feedback_events']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('grant select,insert,update on public.%I to service_role',t);end loop;revoke update on public.sv_feedback_events from service_role;
 for f in select oid::regprocedure signature from pg_proc where pronamespace in('public'::regnamespace,'smartvolt_private'::regnamespace)and proname in('feedback_event','sv_feedback_receipt','sv_feedback_action','sv_feedback_prepare','sv_feedback_claim','sv_feedback_finish','sv_feedback_read')loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;
end;$$;
create trigger sv_feedback_events_immutable before update or delete on public.sv_feedback_events for each row execute function smartvolt_private.wa_reject_rewrite();create trigger sv_feedback_events_no_truncate before truncate on public.sv_feedback_events for each statement execute function smartvolt_private.wa_reject_rewrite();
